import{_ as o,o as c,c as d,a5 as t}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"配置","description":"","frontmatter":{"title":"配置","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","附录","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/附录/未分类/一发入魂/配置.md","filePath":"posts/java快速入门/附录/未分类/一发入魂/配置.md"}'),a={name:"posts/java快速入门/附录/未分类/一发入魂/配置.md"};function p(r,e,s,i,l,n){return c(),d("div",null,[...e[0]||(e[0]=[t("<div><p><code>mybatis plus</code>有许多可配置项，可在<code>application.yml</code>中进行配置，如上面的全局主键策略。下面列举部分配置项</p><p>基本配置</p><ul><li><code>configLocation</code>：若有单独的<code>mybatis</code>配置，用这个注解指定<code>mybatis</code>的配置文件（<code>mybatis</code>的全局配置文件）</li><li><code>mapperLocations</code>：<code>mybatis mapper</code>所对应的<code>xml</code>文件的位置</li><li><code>typeAliasesPackage</code>：<code>mybatis</code>的别名包扫描路径</li><li><code>.....</code></li></ul><p>进阶配置 • <code>mapUnderscoreToCamelCase</code>：是否开启自动驼峰命名规则映射。（默认开启） • <code>dbTpe</code>：数据库类型。一般不用配，会根据数据库连接<code>url</code>自动识别 • <code>fieldStrategy</code>：（已过时）字段验证策略。该配置项在最新版的<code>mp</code>文档中已经找不到了，被细分成了<code>insertStrategy</code>，<code>updateStrategy</code>，<code>selectStrategy</code>。默认值是<code>NOT_NULL</code>，即对于实体对象中非空的字段，才会组装到最终的<code>SQL</code>语句中。 有如下几种可选配置 • <code>IGNORED</code>：忽略校验。即，不做校验。实体对象中的全部字段，无论值是什么，都如实地被组装到<code>SQL</code>语句中（为<code>NULL</code>的字段在<code>SQL</code>语句中就组装为<code>NULL</code>）。 • <code>NOT_NULL</code>：非<code>NULL</code>校验。只会将非<code>NULL</code>的字段组装到<code>SQL</code>语句中 • <code>NOT_EMPTY</code>：非空校验。当有字段是字符串类型时，只组装非空字符串；对其他类型的字段，等同于<code>NOT_NULL</code> • <code>NEVER</code>：不加入<code>SQL</code>。所有字段不加入到<code>SQL</code>语句 这个配置项，可在<code>application.yml</code>中进行全局配置，也可以在某一实体类中，对某一字段用<code>@TableField</code>注解进行局部配置 这个字段验证策略有什么用呢？在<code>UPDATE</code>操作中能够体现出来，若用一个<code>User</code>对象执行<code>UPDATE</code>操作，我们希望只对<code>User</code>对象中非空的属性，更新到数据库中，其他属性不做更新，则<code>NOT_NULL</code>可以满足需求。而若<code>updateStrategy</code>配置为<code>IGNORED</code>，则不会进行非空判断，会将实体对象中的全部属性如实组装到<code>SQL</code>中，这样，执行<code>UPDATE</code>时，可能就将一些不想更新的字段，设置为了<code>NULL</code>。 • <code>tablePrefix</code>：添加表名前缀 比如 <code>mybatis-plus:global-config:db-config:table-prefix:xx_</code>复制代码 然后将<code>MYSQL</code>中的表做一下修改。但<code>Java</code>实体类保持不变（仍然为<code>User</code>）。</p><p>测试</p><p>@Testpublicvoidtest3(){ QueryWrapper&lt;User&gt; wrapper = newQueryWrapper&lt;&gt;(); wrapper.like(&quot;name&quot;, &quot; 黄</p><p>&quot;); Integercount=userMapper.selectCount(wrapper); System.out.println(count); } 复制代码 可以看到拼接出来的<code>SQL</code>，在表名前面添加了前缀</p><p>完整的配置可以参考<code>mp</code>的官网 <code>==\\&gt;</code> 传送门</p></div>",1)])])}const m=o(a,[["render",p]]);export{_ as __pageData,m as default};
